-- D2D curriculum package v1. Content is intentionally versioned and research-pilot scoped.
-- The first module remains the vertical-slice lesson; the following modules are accessible practice lessons.

update public.lessons
set content_version = 'curriculum-1',
    framework_phase = 'Notice -> Try -> Carry',
    content = '{"topic":"credit card interest","source":"Whitney curriculum pilot","objectives":["8.AT.A.1","MD PFL 4"],"steps":[{"id":"notice","title":"Slow down before you decide.","prompt":"A statement is not a wall of numbers. Start by locating the new balance, minimum payment, APR, and payment due date."},{"id":"try","title":"Name the tradeoff.","prompt":"Paying only the minimum may protect you from a late fee today, but it usually keeps the balance around longer."},{"id":"carry","title":"Carry the question forward.","prompt":"What does this number measure? What choice does it unlock? What evidence would change my mind?"}],"accessibility":{"no_countdown":true,"keyboard_first":true,"reduced_motion_safe":true,"plain_language":true}}'::jsonb
where slug = 'the-money-you-pay';

insert into public.lessons(id,program_id,slug,title,framework_phase,content_version,content,status)
select '66666666-6666-4666-8666-666666666667', p.id, 'credit-choices', 'Credit Choices', 'Notice -> Try -> Carry', 'curriculum-1', '{"topic":"credit tradeoffs","source":"Whitney curriculum pilot","objectives":["8.AT.B.3","MD PFL 1","MD PFL 4"],"steps":[{"id":"compare","title":"Put both offers on the same page.","prompt":"A lower monthly payment can hide a longer payoff or a higher total cost. Build a side-by-side comparison before choosing."},{"id":"question","title":"Ask what the offer costs over time.","prompt":"Find the fee, interest rate, length of repayment, and total amount paid. Circle the detail that could change your decision."},{"id":"justify","title":"Explain your choice.","prompt":"Choose the offer that fits the scenario and explain the tradeoff in one or two sentences."}],"accessibility":{"no_countdown":true,"keyboard_first":true,"reduced_motion_safe":true,"plain_language":true}}'::jsonb, 'published'
from public.programs p where p.slug = 'd2d-pilot'
on conflict (id) do update set content = excluded.content, content_version = excluded.content_version, status = excluded.status;

insert into public.lessons(id,program_id,slug,title,framework_phase,content_version,content,status)
select '66666666-6666-4666-8666-666666666668', p.id, 'payment-plan-model', 'Payment Plan Model', 'Notice -> Try -> Carry', 'curriculum-1', '{"topic":"functions and modeling","source":"Whitney curriculum pilot","objectives":["8.AT.D","8.F.B","MD PFL 3"],"steps":[{"id":"table","title":"Find the pattern in the table.","prompt":"A table shows what changes each month and what stays the same. Look for the rate of change before reaching for a formula."},{"id":"equation","title":"Choose a useful representation.","prompt":"Translate the pattern into an equation or graph. Check whether the representation still makes sense when you test a new value."},{"id":"interpret","title":"Interpret, then challenge the model.","prompt":"State what the answer means in the real situation and name one assumption that could make the model less accurate."}],"accessibility":{"no_countdown":true,"keyboard_first":true,"reduced_motion_safe":true,"plain_language":true}}'::jsonb, 'published'
from public.programs p where p.slug = 'd2d-pilot'
on conflict (id) do update set content = excluded.content, content_version = excluded.content_version, status = excluded.status;

insert into public.lessons(id,program_id,slug,title,framework_phase,content_version,content,status)
select '66666666-6666-4666-8666-666666666669', p.id, 'carry-it-forward', 'Carry It Forward', 'Notice -> Try -> Carry', 'curriculum-1', '{"topic":"transfer and decision making","source":"Whitney curriculum pilot","objectives":["8.AT.B.4","MD PFL 1","MD PFL 3"],"steps":[{"id":"notice","title":"What is actually being asked?","prompt":"Separate the story from the signal. Identify the quantities, the constraint, and the decision the person needs to make."},{"id":"transfer","title":"Reuse the strategy, not the answer.","prompt":"Bring forward the questions that helped you before, but rebuild the model for this situation. Transfer means adapting."},{"id":"reflect","title":"Make your thinking visible.","prompt":"Write the decision, the evidence, and the next question. Your explanation is part of the work, not an afterthought."}],"accessibility":{"no_countdown":true,"keyboard_first":true,"reduced_motion_safe":true,"plain_language":true}}'::jsonb, 'published'
from public.programs p where p.slug = 'd2d-pilot'
on conflict (id) do update set content = excluded.content, content_version = excluded.content_version, status = excluded.status;
